            # Only consider edges in the majority 50% consensus graph
            if prob < 0.5:
                continue
            source, target, num = edge.split("_")

            if source == primary_tissue:
                ps_values.append(prob)
            elif target == primary_tissue:
                pr_values.append(prob)
            else:
                mm_values.append(prob)

